import React, { useEffect, useState } from "react";
import { API_BASE } from "../config";

const today = () => new Date().toISOString().split("T")[0];

const Shows = () => {
  const [shows, setShows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState(null);
  const [editData, setEditData] = useState({});
  const [toast, setToast] = useState({ msg: "", type: "success" });
  const [formData, setFormData] = useState({
    name: "",
    date: today(),
    location: "",
    tableFee: "",
    travelCost: "",
    notes: "",
  });

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast({ msg: "", type: "success" }), 3000);
  };

  const fetchShows = async () => {
    const res = await fetch(`${API_BASE}/api/shows`);
    const data = await res.json();
    setShows(data);
    setLoading(false);
  };

  useEffect(() => {
    fetchShows();
  }, []);

  const handleChange = (e) =>
    setFormData((p) => ({ ...p, [e.target.name]: e.target.value }));
  const handleEditChange = (e) =>
    setEditData((p) => ({ ...p, [e.target.name]: e.target.value }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    const res = await fetch(`${API_BASE}/api/shows`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(formData),
    });
    if (res.ok) {
      setFormData({
        name: "",
        date: today(),
        location: "",
        tableFee: "",
        travelCost: "",
        notes: "",
      });
      showToast("✓ Show added!");
      fetchShows();
    } else {
      const d = await res.json();
      showToast("Error: " + d.error, "error");
    }
  };

  const handleEdit = (show) => {
    setEditingId(show._id);
    setEditData({
      name: show.name,
      date: new Date(show.date).toISOString().split("T")[0],
      location: show.location || "",
      tableFee: show.tableFee || "",
      travelCost: show.travelCost || "",
      notes: show.notes || "",
    });
  };

  const handleEditSave = async (id) => {
    const res = await fetch(`${API_BASE}/api/shows/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(editData),
    });
    if (res.ok) {
      setEditingId(null);
      showToast("✓ Show updated!");
      fetchShows();
    } else {
      const d = await res.json();
      showToast("Error: " + d.error, "error");
    }
  };

  const handleDelete = async (id, name) => {
    if (
      !window.confirm(
        `Delete "${name}"? Sales linked to this show will become Unassigned.`,
      )
    )
      return;
    await fetch(`${API_BASE}/api/shows/${id}`, { method: "DELETE" });
    showToast("Show deleted.");
    fetchShows();
  };

  const fmt = (n) => `$${Number(n || 0).toFixed(2)}`;

  return (
    <div>
      <h1 className="page-title">Shows</h1>

      {/* Add Show Form */}
      <div className="card" style={{ maxWidth: 700, marginBottom: 28 }}>
        <p className="form-label" style={{ marginBottom: 16 }}>
          Add Show
        </p>
        <form onSubmit={handleSubmit} className="form-grid" style={{ gap: 14 }}>
          <div className="form-grid form-grid-2">
            <div className="form-group">
              <label className="form-label">Show Name *</label>
              <input
                className="form-input"
                name="name"
                placeholder="e.g. Denver Card Show"
                value={formData.name}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label">Date *</label>
              <input
                className="form-input"
                type="date"
                name="date"
                value={formData.date}
                onChange={handleChange}
                required
              />
            </div>
          </div>
          <div className="form-group">
            <label className="form-label">Location</label>
            <input
              className="form-input"
              name="location"
              placeholder="e.g. Denver Convention Center"
              value={formData.location}
              onChange={handleChange}
            />
          </div>
          <div className="form-grid form-grid-2">
            <div className="form-group">
              <label className="form-label">Table / Booth Fee ($)</label>
              <input
                className="form-input"
                type="number"
                name="tableFee"
                placeholder="0.00"
                step="0.01"
                min="0"
                value={formData.tableFee}
                onChange={handleChange}
              />
            </div>
            <div className="form-group">
              <label className="form-label">Travel Cost ($)</label>
              <input
                className="form-input"
                type="number"
                name="travelCost"
                placeholder="0.00"
                step="0.01"
                min="0"
                value={formData.travelCost}
                onChange={handleChange}
              />
            </div>
          </div>
          <div className="form-group">
            <label className="form-label">Notes</label>
            <input
              className="form-input"
              name="notes"
              placeholder="Optional notes..."
              value={formData.notes}
              onChange={handleChange}
            />
          </div>
          <button type="submit" className="btn btn-primary">
            Add Show
          </button>
        </form>
      </div>

      {/* Shows List */}
      {loading ? (
        <div
          className="skeleton"
          style={{ height: 200, borderRadius: "var(--radius)" }}
        />
      ) : shows.length === 0 ? (
        <div
          className="card"
          style={{
            textAlign: "center",
            padding: 48,
            color: "var(--text-muted)",
          }}
        >
          No shows yet. Add your first show above.
        </div>
      ) : (
        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Date</th>
                <th>Location</th>
                <th>Table Fee</th>
                <th>Travel</th>
                <th>Notes</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {shows.map((show) => (
                <tr key={show._id}>
                  {editingId === show._id ? (
                    <>
                      <td>
                        <input
                          className="form-input"
                          name="name"
                          value={editData.name}
                          onChange={handleEditChange}
                          style={{ minWidth: 140 }}
                        />
                      </td>
                      <td>
                        <input
                          className="form-input"
                          type="date"
                          name="date"
                          value={editData.date}
                          onChange={handleEditChange}
                        />
                      </td>
                      <td>
                        <input
                          className="form-input"
                          name="location"
                          value={editData.location}
                          onChange={handleEditChange}
                          style={{ minWidth: 140 }}
                        />
                      </td>
                      <td>
                        <input
                          className="form-input"
                          type="number"
                          name="tableFee"
                          value={editData.tableFee}
                          onChange={handleEditChange}
                          style={{ minWidth: 80 }}
                        />
                      </td>
                      <td>
                        <input
                          className="form-input"
                          type="number"
                          name="travelCost"
                          value={editData.travelCost}
                          onChange={handleEditChange}
                          style={{ minWidth: 80 }}
                        />
                      </td>
                      <td>
                        <input
                          className="form-input"
                          name="notes"
                          value={editData.notes}
                          onChange={handleEditChange}
                          style={{ minWidth: 120 }}
                        />
                      </td>
                      <td>
                        <div style={{ display: "flex", gap: 6 }}>
                          <button
                            className="btn btn-success btn-sm"
                            onClick={() => handleEditSave(show._id)}
                          >
                            Save
                          </button>
                          <button
                            className="btn btn-secondary btn-sm"
                            onClick={() => setEditingId(null)}
                          >
                            Cancel
                          </button>
                        </div>
                      </td>
                    </>
                  ) : (
                    <>
                      <td style={{ fontWeight: 600 }}>{show.name}</td>
                      <td style={{ color: "var(--text-muted)" }}>
                        {new Date(show.date).toLocaleDateString()}
                      </td>
                      <td style={{ color: "var(--text-muted)" }}>
                        {show.location || "—"}
                      </td>
                      <td style={{ color: "var(--danger)" }}>
                        {show.tableFee > 0 ? fmt(show.tableFee) : "—"}
                      </td>
                      <td style={{ color: "var(--danger)" }}>
                        {show.travelCost > 0 ? fmt(show.travelCost) : "—"}
                      </td>
                      <td
                        style={{
                          color: "var(--text-muted)",
                          fontStyle: "italic",
                        }}
                      >
                        {show.notes || "—"}
                      </td>
                      <td>
                        <div style={{ display: "flex", gap: 6 }}>
                          <button
                            className="btn btn-secondary btn-sm"
                            onClick={() => handleEdit(show)}
                          >
                            Edit
                          </button>
                          <button
                            className="btn btn-danger btn-sm"
                            onClick={() => handleDelete(show._id, show.name)}
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {toast.msg && (
        <div className={`toast toast-${toast.type}`}>{toast.msg}</div>
      )}
    </div>
  );
};

export default Shows;
