import React, { useEffect, useState } from "react";
import { API_BASE } from "../config";

const MIN_DATE = new Date("2020-01-01");
const isValidDate = (d) => {
  const date = new Date(d);
  return d && !isNaN(date.getTime()) && date >= MIN_DATE;
};
const daysBetween = (a, b) =>
  Math.round(Math.abs(new Date(b) - new Date(a)) / (1000 * 60 * 60 * 24));
const today = () => new Date().toISOString().split("T")[0];

const typeBadge = (type) => {
  const cls = {
    Card: "badge-card",
    Slab: "badge-slab",
    Sealed: "badge-sealed",
  };
  return <span className={`badge ${cls[type] || ""}`}>{type}</span>;
};

const paymentBadge = (method) => {
  if (!method || method === "Cash")
    return (
      <span
        className="badge"
        style={{ background: "rgba(76,175,125,0.15)", color: "var(--green)" }}
      >
        Cash
      </span>
    );
  if (method === "Digital - Ben")
    return (
      <span
        className="badge"
        style={{ background: "rgba(74,179,216,0.15)", color: "var(--blue)" }}
      >
        Digital - Ben
      </span>
    );
  if (method === "Digital - Owen")
    return (
      <span
        className="badge"
        style={{ background: "rgba(232,184,75,0.12)", color: "var(--accent)" }}
      >
        Digital - Owen
      </span>
    );
  return null;
};

const AgingBadge = ({ daysHeld }) => {
  if (daysHeld === null) return null;
  const color =
    daysHeld > 60 ? "#e05c5c" : daysHeld > 30 ? "#e8b84b" : "#4caf7d";
  const label =
    daysHeld > 60
      ? `${daysHeld}d — Reprice?`
      : daysHeld > 30
        ? `${daysHeld}d — Watch`
        : `${daysHeld}d`;
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 5,
        fontSize: 11,
        fontWeight: 600,
        color,
        background: `${color}18`,
        padding: "2px 7px",
        borderRadius: 4,
      }}
    >
      <span
        style={{
          width: 7,
          height: 7,
          borderRadius: "50%",
          background: color,
          display: "inline-block",
          flexShrink: 0,
        }}
      />
      {label}
    </span>
  );
};

const resolveSource = (sourcedFrom, showNameMap) => {
  if (!sourcedFrom) return null;
  if (sourcedFrom === "Online" || sourcedFrom === "Private Sale")
    return sourcedFrom;
  return showNameMap[sourcedFrom] || "Unknown Show";
};

const ItemsTable = () => {
  const [items, setItems] = useState([]);
  const [shows, setShows] = useState([]);
  const [showSold, setShowSold] = useState(false);
  const [typeFilter, setTypeFilter] = useState("All");
  const [searchQuery, setSearchQuery] = useState("");
  const [agingFilter, setAgingFilter] = useState("All");
  const [editingItemId, setEditingItemId] = useState(null);
  const [soldData, setSoldData] = useState({
    soldPrice: "",
    soldDate: today(),
    paymentMethod: "Cash",
    soldAtShow: "",
    notes: "",
  });
  const [toast, setToast] = useState({ msg: "", type: "success" });
  const [loading, setLoading] = useState(true);

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast({ msg: "", type: "success" }), 3000);
  };
  const fetchItems = async () => {
    const res = await fetch(`${API_BASE}/api/items`);
    const data = await res.json();
    setItems(data);
    setLoading(false);
  };
  const fetchShows = async () => {
    const res = await fetch(`${API_BASE}/api/shows`);
    const data = await res.json();
    setShows(data);
  };

  useEffect(() => {
    fetchItems();
    fetchShows();
  }, []);

  const handleEditChange = (e) =>
    setSoldData({ ...soldData, [e.target.name]: e.target.value });

  const handleMarkSold = (item) => {
    setEditingItemId(item._id);
    setSoldData({
      soldPrice: "",
      soldDate: today(),
      paymentMethod: "Cash",
      soldAtShow: "",
      notes: item.notes || "",
    });
  };

  const handleSubmit = async (itemId) => {
    const payload = { ...soldData };
    if (!payload.soldAtShow) delete payload.soldAtShow;
    const res = await fetch(`${API_BASE}/api/items/${itemId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (res.ok) {
      setEditingItemId(null);
      setSoldData({
        soldPrice: "",
        soldDate: today(),
        paymentMethod: "Cash",
        soldAtShow: "",
        notes: "",
      });
      showToast("✓ Item marked as sold!");
      fetchItems();
    } else {
      const data = await res.json();
      showToast("Error: " + data.error, "error");
    }
  };

  const handleDelete = async (id, name) => {
    if (!window.confirm(`Delete "${name}"? This cannot be undone.`)) return;
    await fetch(`${API_BASE}/api/items/${id}`, { method: "DELETE" });
    showToast("Item deleted.");
    fetchItems();
  };

  const showNameMap = {};
  shows.forEach((s) => {
    showNameMap[s._id] = s.name;
  });

  const nowDate = new Date();

  const filteredItems = items.filter((item) => {
    const soldCondition = showSold || item.soldPrice == null;
    const typeCondition = typeFilter === "All" || item.itemType === typeFilter;
    const q = searchQuery.toLowerCase();
    const searchCondition =
      item.name.toLowerCase().includes(q) ||
      (item.set && item.set.toLowerCase().includes(q)) ||
      (item.number && item.number.toLowerCase().includes(q)) ||
      (item.owner && item.owner.toLowerCase().includes(q));
    let agingCondition = true;
    if (agingFilter !== "All" && item.soldPrice == null) {
      const daysHeld = isValidDate(item.purchaseDate)
        ? daysBetween(item.purchaseDate, nowDate)
        : null;
      if (agingFilter === "fresh")
        agingCondition = daysHeld !== null && daysHeld <= 29;
      if (agingFilter === "aging")
        agingCondition = daysHeld !== null && daysHeld >= 30 && daysHeld <= 60;
      if (agingFilter === "stale")
        agingCondition = daysHeld !== null && daysHeld > 60;
    }
    return soldCondition && typeCondition && searchCondition && agingCondition;
  });

  if (loading)
    return (
      <div>
        <h1 className="page-title">Inventory</h1>
        <div className="inventory-grid">
          {Array(6)
            .fill(0)
            .map((_, i) => (
              <div key={i} className="card">
                <div
                  className="skeleton"
                  style={{ height: 16, width: "70%", marginBottom: 14 }}
                />
                <div
                  className="skeleton"
                  style={{ height: 12, width: "50%", marginBottom: 8 }}
                />
                <div
                  className="skeleton"
                  style={{ height: 12, width: "90%", marginBottom: 8 }}
                />
                <div
                  className="skeleton"
                  style={{ height: 12, width: "60%" }}
                />
              </div>
            ))}
        </div>
      </div>
    );

  return (
    <div>
      <div className="section-header">
        <h1 className="page-title" style={{ marginBottom: 0 }}>
          Inventory
        </h1>
        <span style={{ color: "var(--text-muted)", fontSize: 14 }}>
          {filteredItems.length} item{filteredItems.length !== 1 ? "s" : ""}
        </span>
      </div>

      <div className="filter-bar">
        <button
          className={`btn btn-sm ${showSold ? "btn-secondary" : "btn-primary"}`}
          onClick={() => setShowSold((p) => !p)}
        >
          {showSold ? "Hide Sold" : "Show Sold"}
        </button>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span className="form-label" style={{ marginBottom: 0 }}>
            Type:
          </span>
          <select
            className="form-select"
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            style={{ width: "auto" }}
          >
            <option value="All">All</option>
            <option value="Card">Card</option>
            <option value="Slab">Slab</option>
            <option value="Sealed">Sealed</option>
          </select>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span className="form-label" style={{ marginBottom: 0 }}>
            Age:
          </span>
          <select
            className="form-select"
            value={agingFilter}
            onChange={(e) => setAgingFilter(e.target.value)}
            style={{ width: "auto" }}
          >
            <option value="All">All</option>
            <option value="fresh">🟢 Fresh (0–29d)</option>
            <option value="aging">🟡 Aging (30–60d)</option>
            <option value="stale">🔴 Stale (60d+)</option>
          </select>
        </div>
        <input
          type="text"
          className="form-input"
          placeholder="Search name, set, number, owner..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={{ flex: "1 1 200px" }}
        />
      </div>

      {filteredItems.length === 0 ? (
        <div
          className="card"
          style={{
            textAlign: "center",
            padding: 48,
            color: "var(--text-muted)",
          }}
        >
          No items match your filters.
        </div>
      ) : (
        <div className="inventory-grid">
          {filteredItems.map((item) => {
            const soldPrice = Number(item.soldPrice);
            const purchasePrice = Number(item.purchasePrice);
            const profit =
              item.soldPrice != null ? soldPrice - purchasePrice : null;
            const marginPct =
              item.soldPrice != null && soldPrice > 0
                ? (((soldPrice - purchasePrice) / soldPrice) * 100).toFixed(1)
                : null;
            const soldShowName = item.soldAtShow
              ? showNameMap[item.soldAtShow]
              : null;
            const sourcedFromLabel = resolveSource(
              item.sourcedFrom,
              showNameMap,
            );
            const daysHeld =
              item.soldPrice == null && isValidDate(item.purchaseDate)
                ? daysBetween(item.purchaseDate, nowDate)
                : null;

            // Time to sell for sold items
            const timeToSell =
              item.soldPrice != null &&
              isValidDate(item.purchaseDate) &&
              isValidDate(item.soldDate)
                ? daysBetween(item.purchaseDate, item.soldDate)
                : null;

            return (
              <div
                key={item._id}
                className={`item-card ${item.soldPrice != null ? "item-card--sold" : ""}`}
                style={
                  daysHeld !== null && daysHeld > 60
                    ? { borderColor: "rgba(224,92,92,0.35)" }
                    : daysHeld !== null && daysHeld > 30
                      ? { borderColor: "rgba(232,184,75,0.35)" }
                      : {}
                }
              >
                <div className="item-card__header">
                  <div>
                    <div className="item-card__name">{item.name}</div>
                    {daysHeld !== null && (
                      <div style={{ marginTop: 4 }}>
                        <AgingBadge daysHeld={daysHeld} />
                      </div>
                    )}
                  </div>
                  <div
                    style={{
                      display: "flex",
                      gap: 5,
                      flexShrink: 0,
                      flexWrap: "wrap",
                    }}
                  >
                    {typeBadge(item.itemType)}
                    {item.soldPrice != null ? (
                      <span className="badge badge-sold">Sold</span>
                    ) : (
                      <span className="badge badge-unsold">Active</span>
                    )}
                  </div>
                </div>

                {item.itemType === "Card" && (
                  <div className="item-card__row">
                    <span className="item-card__row-label">Set / # / Cond</span>
                    <span className="item-card__row-value">
                      {item.set || "—"} · {item.number || "—"} ·{" "}
                      {item.condition || "—"}
                    </span>
                  </div>
                )}
                {item.itemType === "Slab" && (
                  <div className="item-card__row">
                    <span className="item-card__row-label">Grade</span>
                    <span className="item-card__row-value">
                      {item.company || "—"} {item.grade || "—"}
                    </span>
                  </div>
                )}

                <div className="item-card__row">
                  <span className="item-card__row-label">Owner</span>
                  <span className="item-card__row-value">
                    {item.owner || "—"}
                  </span>
                </div>

                <div className="item-card__row">
                  <span className="item-card__row-label">Bought</span>
                  <span className="item-card__row-value">
                    ${purchasePrice.toFixed(2)}
                    {item.purchaseDate
                      ? ` · ${new Date(item.purchaseDate).toLocaleDateString()}`
                      : ""}
                  </span>
                </div>

                <div className="item-card__row">
                  <span className="item-card__row-label">Sourced From</span>
                  <span
                    className="item-card__row-value"
                    style={{
                      color: sourcedFromLabel
                        ? sourcedFromLabel === "Online"
                          ? "var(--blue)"
                          : sourcedFromLabel === "Private Sale"
                            ? "var(--accent)"
                            : "var(--green)"
                        : "var(--text-muted)",
                      fontStyle: sourcedFromLabel ? "normal" : "italic",
                    }}
                  >
                    {sourcedFromLabel || "Unassigned"}
                  </span>
                </div>

                {item.soldPrice != null && (
                  <>
                    <div className="item-card__row">
                      <span className="item-card__row-label">Sold</span>
                      <span className="item-card__row-value">
                        ${soldPrice.toFixed(2)}
                        {item.soldDate
                          ? ` · ${new Date(item.soldDate).toLocaleDateString()}`
                          : ""}
                      </span>
                    </div>
                    <div className="item-card__row">
                      <span className="item-card__row-label">Sold At</span>
                      <span
                        className="item-card__row-value"
                        style={{
                          color: soldShowName
                            ? "var(--green)"
                            : "var(--text-muted)",
                          fontStyle: soldShowName ? "normal" : "italic",
                        }}
                      >
                        {soldShowName || "Unassigned"}
                      </span>
                    </div>
                    <div className="item-card__row">
                      <span className="item-card__row-label">Payment</span>
                      <span className="item-card__row-value">
                        {paymentBadge(item.paymentMethod)}
                      </span>
                    </div>
                    {timeToSell !== null && (
                      <div className="item-card__row">
                        <span className="item-card__row-label">
                          Time to Sell
                        </span>
                        <span
                          className="item-card__row-value"
                          style={{ color: "var(--text-muted)" }}
                        >
                          {timeToSell === 0
                            ? "Same day"
                            : `${timeToSell} day${timeToSell !== 1 ? "s" : ""}`}
                        </span>
                      </div>
                    )}
                  </>
                )}

                {profit !== null && (
                  <div className="item-card__row">
                    <span className="item-card__row-label">Profit</span>
                    <span
                      style={{
                        fontWeight: 700,
                        color: profit >= 0 ? "var(--green)" : "var(--danger)",
                        display: "flex",
                        gap: 6,
                        alignItems: "center",
                      }}
                    >
                      <span>
                        {profit >= 0 ? "+" : ""}${profit.toFixed(2)}
                      </span>
                      <span
                        style={{
                          fontSize: 11,
                          fontWeight: 600,
                          background:
                            profit >= 0
                              ? "rgba(76,175,125,0.15)"
                              : "rgba(224,92,92,0.15)",
                          color: profit >= 0 ? "var(--green)" : "var(--danger)",
                          padding: "1px 6px",
                          borderRadius: 4,
                        }}
                      >
                        {marginPct}%
                      </span>
                    </span>
                  </div>
                )}

                {item.notes && (
                  <div className="item-card__row">
                    <span className="item-card__row-label">Notes</span>
                    <span
                      className="item-card__row-value"
                      style={{ fontStyle: "italic" }}
                    >
                      {item.notes}
                    </span>
                  </div>
                )}

                {item.soldPrice == null && editingItemId === item._id && (
                  <div className="sell-form">
                    <div className="form-group">
                      <label className="form-label">Sold Price</label>
                      <input
                        type="number"
                        name="soldPrice"
                        className="form-input"
                        value={soldData.soldPrice}
                        onChange={handleEditChange}
                        placeholder="0.00"
                        step="0.01"
                        min="0"
                        autoFocus
                      />
                    </div>
                    <div className="form-group">
                      <label className="form-label">Sold Date</label>
                      <input
                        type="date"
                        name="soldDate"
                        className="form-input"
                        value={soldData.soldDate}
                        onChange={handleEditChange}
                      />
                    </div>
                    <div className="form-group">
                      <label className="form-label">Payment Method</label>
                      <select
                        name="paymentMethod"
                        className="form-select"
                        value={soldData.paymentMethod}
                        onChange={handleEditChange}
                      >
                        <option value="Cash">Cash</option>
                        <option value="Digital - Ben">Digital - Ben</option>
                        <option value="Digital - Owen">Digital - Owen</option>
                      </select>
                    </div>
                    <div className="form-group">
                      <label className="form-label">Sold At</label>
                      <select
                        name="soldAtShow"
                        className="form-select"
                        value={soldData.soldAtShow}
                        onChange={handleEditChange}
                      >
                        <option value="">— Unassigned —</option>
                        <option value="Online">Online</option>
                        <option value="Private Sale">Private Sale</option>
                        {shows.length > 0 && (
                          <>
                            <option disabled>──── Shows ────</option>
                            {shows.map((s) => (
                              <option key={s._id} value={s._id}>
                                {s.name} (
                                {new Date(s.date).toLocaleDateString()})
                              </option>
                            ))}
                          </>
                        )}
                      </select>
                    </div>
                    <div className="form-group">
                      <label className="form-label">Notes</label>
                      <input
                        type="text"
                        name="notes"
                        className="form-input"
                        value={soldData.notes}
                        onChange={handleEditChange}
                        placeholder="Optional..."
                      />
                    </div>
                  </div>
                )}

                <div className="item-card__actions">
                  {item.soldPrice == null &&
                    (editingItemId === item._id ? (
                      <>
                        <button
                          className="btn btn-success btn-sm"
                          onClick={() => handleSubmit(item._id)}
                        >
                          Save
                        </button>
                        <button
                          className="btn btn-secondary btn-sm"
                          onClick={() => setEditingItemId(null)}
                        >
                          Cancel
                        </button>
                      </>
                    ) : (
                      <button
                        className="btn btn-primary btn-sm"
                        onClick={() => handleMarkSold(item)}
                      >
                        Mark as Sold
                      </button>
                    ))}
                  <button
                    className="btn btn-danger btn-sm"
                    onClick={() => handleDelete(item._id, item.name)}
                    style={{ marginLeft: "auto" }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {toast.msg && (
        <div className={`toast toast-${toast.type}`}>{toast.msg}</div>
      )}
    </div>
  );
};

export default ItemsTable;
